package com.bank.cache;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class CacheConcurrencyTest {

    // ═══ HashMap: lost updates under concurrency ═══
    @Test
    void hashMap_lostUpdates() throws InterruptedException {
        Map<Integer, Integer> unsafeCache = new HashMap<>();
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            final int id = t;
            new Thread(() -> {
                for (int i = 0; i < 100; i++) {
                    unsafeCache.put(id * 100 + i, i);
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        System.out.println("HashMap entries: " + unsafeCache.size() + " (expected 10000)");
        // Often < 10000! Lost puts due to race condition!
    }

    // ═══ ConcurrentHashMap: zero lost updates ═══
    @Test
    void concurrentHashMap_noLostUpdates() throws InterruptedException {
        ConcurrentHashMap<Integer, Integer> safeCache = new ConcurrentHashMap<>();
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            final int id = t;
            new Thread(() -> {
                for (int i = 0; i < 100; i++) {
                    safeCache.put(id * 100 + i, i);
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(safeCache).hasSize(10000);  // ALWAYS 10000! Zero lost!
    }

    // ═══ ConcurrentHashMap: atomic computeIfAbsent ═══
    @Test
    void computeIfAbsent_atomicCacheLoad() throws InterruptedException {
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        AtomicInteger loadCount = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                cache.computeIfAbsent("SAV2001", k -> {
                    loadCount.incrementAndGet();
                    return "BALANCE:100000";
                });
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(loadCount.get()).isEqualTo(1);  // loaded ONCE! Atomic!
        assertThat(cache.get("SAV2001")).isEqualTo("BALANCE:100000");
    }
}
